ByteDance2ReferenceNodeV2.expr:
(
  $m := widgets.model;
  $res := $lookup(widgets, "model.resolution");
  $ratio := $lookup(widgets, "model.ratio");
  $dur := $lookup(widgets, "model.duration");
  $auto := $lookup(widgets, "model.task_type") = "edit";
  $hasVideo := $exists(inputGroups) and $lookup(inputGroups, "model.reference_videos") > 0;
  $ready := $type($m) = "string" and $type($res) = "string" and ($auto or $type($dur) = "number");
  $ready ? (
    $contains($m, "2.5") ? (
      $is480 := $res = "480p";
      $is1080 := $res = "1080p";
      $is4k := $res = "4k";
      $perFrame := $ratio = "1:1"  ? ($is480 ? 400      : $is1080 ? 2025      : $is4k ? 8100      : 900) :
                   $ratio = "4:3"  ? ($is480 ? 411.25   : $is1080 ? 2028      : $is4k ? 8100.6289 : 905.6719) :
                   $ratio = "3:4"  ? ($is480 ? 411.25   : $is1080 ? 2028      : $is4k ? 8100.6289 : 905.6719) :
                   $ratio = "21:9" ? ($is480 ? 418.5    : $is1080 ? 2037.9648 : $is4k ? 8100.2227 : 904.3945) :
                                     ($is480 ? 400.3125 : $is1080 ? 2025      : $is4k ? 8100      : 900);
      $price := $is4k   ? ($hasVideo ? 0.004147 : 0.006721) :
                $is1080 ? ($hasVideo ? 0.01001 : 0.016731) :
                          ($hasVideo ? 0.009152 : 0.015301);
      $costFor := function($d) { $floor($perFrame * (24 * $d + 1)) / 1000 * $price };
      $lo := $costFor($auto ? 4 : $dur);
      $hi := $costFor(($auto ? 30 : $dur) + ($hasVideo ? 30 : 0));
      $lo = $hi
        ? {"type": "usd", "usd": $lo, "format": {"approximate": true}}
        : {"type": "range_usd", "min_usd": $lo, "max_usd": $hi, "format": {"approximate": true}}
    ) : (
      $rate := $res = "4k"    ? 195200 :
               $res = "1080p" ? 48800 :
               $res = "720p"  ? 21600 : 10044;
      $noVideoPrice := $res = "4k"    ? 0.00572 :
                       $res = "1080p" ? 0.011011 :
                       $contains($m, "mini") ? 0.005005 :
                       $contains($m, "fast") ? 0.008008 : 0.01001;
      $videoPrice := $res = "4k"    ? 0.003432 :
                     $res = "1080p" ? 0.006721 :
                     $contains($m, "mini") ? 0.003003 :
                     $contains($m, "fast") ? 0.004719 : 0.006149;
      $hasVideo
        ? {"type": "range_usd",
           "min_usd": $ceil($dur * 5 / 3) * $rate * $videoPrice / 1000,
           "max_usd": (15 + $dur) * $rate * $videoPrice / 1000,
           "format": {"approximate": true}}
        : {"type": "usd", "usd": $dur * $rate * $noVideoPrice / 1000,
           "format": {"approximate": true}}
    )
  ) : undefined
)

LtxApi25ImageToVideo.expr:
(
  $prices := {
    "ltx-2.5 (fast)": {
      "1280x720":0.1287,"720x1280":0.1287,
      "1920x1080":0.1859,"1080x1920":0.1859,
      "2560x1440":0.2717,"1440x2560":0.2717,
      "3840x2160":0.429,"2160x3840":0.429
    },
    "ltx-2.5 (pro)": {
      "1280x720":0.1716,"720x1280":0.1716,
      "1920x1080":0.2431,"1080x1920":0.2431
    }
  };
  $model := $lookup(widgets, "model");
  $table := $type($model) = "string" ? $lookup($prices, $model) : undefined;
  $res := $lookup(widgets, "model.resolution");
  $pps := $type($table) = "object" and $type($res) = "string" ? $lookup($table, $res) : undefined;
  $durRaw := $lookup(widgets, "model.duration");
  $dur := $type($durRaw) in ["string", "number"] ? $number($durRaw) : undefined;
  $type($pps) = "number" and $type($dur) = "number"
    ? {"type":"usd","usd": $pps * $dur}
    : undefined
)

